# Each thunk is typically 8 bytes (2 instructions). Let me calculate which page/offset each refers to.
# Actually, let me just use a different approach. The thunk names encode the page.
# Let me find the specific thunk for each PC:

nm -n libmonosgen-2.0.so.debug 2>/dev/null | awk '
/^[0-9a-f]+ [tTwW]/ {
  addr = strtonum("0x"$1)
  if (addr <= 0x2f4b20) { n1=$3; a1=$1 }
  if (addr <= 0x2f4c84) { n2=$3; a2=$1 }
}
END { print "0x2f4b20: " n1 " at 0x" a1; print "0x2f4c84: " n2 " at 0x" a2 }'", "description": "Find specific thunks for each PC"}

